from decimal import Decimal as D
ledger   = {"T1": D("12000"), "T2": D("5500"), "T3": D("30000"), "T4": D("8900")}
acquirer = {"T1": D("12000"), "T2": D("5000"), "T4": D("8900"), "T5": D("4300")}
for tid in sorted(ledger.keys() | acquirer.keys()):
    a, b = ledger.get(tid), acquirer.get(tid)
    if a is None:   print(tid, "우리 원장에 없음  (카드사", b, ")")
    elif b is None: print(tid, "카드사 파일에 없음 (우리", a, ")")
    elif a != b:    print(tid, "금액 다름", a, "vs", b, "차이", a - b)
# T2 금액 다름 5500 vs 5000 차이 500
# T3 카드사 파일에 없음 (우리 30000 )
# T5 우리 원장에 없음  (카드사 4300 )
